const gql = $input.first().json;
if (gql.errors || !gql.data || !gql.data.node) return [];
const item = gql.data.node;
const status = item.fieldValueByName ? item.fieldValueByName.name : '';
if (status !== 'AI Ready') return [];
const content = item.content;
return [{
  json: {
    issue_number: content.number,
    issue_title: content.title,
    issue_body: content.body || '',
    labels: content.labels.nodes.map(l => l.name),
    repo: content.repository.nameWithOwner,
    project_item_node_id: item.id
  }
}];

const data = $input.first().json;
const labels = (data.labels || []).map(l => l.toLowerCase());
const prefixMap = {
  bug: 'b', feature: 'f', refactoring: 'r',
  operations: 'o', 'docs & research': 'd', enhancement: 'e'
};
let prefix = 'e';
for (const [label, p] of Object.entries(prefixMap)) {
  if (labels.includes(label)) { prefix = p; break; }
}
const slug = (data.issue_title || 'task')
  .toLowerCase().replace(/[^a-z0-9]+/g, '-').substring(0, 40).replace(/-$/, '');
const branchName = `${prefix}/#${data.issue_number}-${slug}`;
return [{ json: {
  branch_name: branchName, repo: data.repo, issue_number: data.issue_number,
  issue_title: data.issue_title, issue_body: data.issue_body,
  project_item_node_id: data.project_item_node_id
} }];

const sha = $input.first().json.object.sha;
const ctx = $('Prepare Context').first().json;
return [{ json: { ref: 'refs/heads/' + ctx.branch_name, sha, ...ctx } }];

const ctx = $('Prepare Branch Data').first().json;
const requestBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 2048,
  messages: [{
    role: 'user',
    content: 'You are a senior software architect. Analyze the following GitHub issue and provide your response in EXACTLY this format:

'      + 'SUMMARY: [one sentence describing the implementation approach]
'      + '---
'      + '[full detailed analysis including:
'      + '1. Implementation approach (step-by-step)
'      + '2. Files likely affected
'      + '3. Risks and considerations
'      + '4. Estimated complexity (Low/Medium/High)]

'      + 'Issue title: ' + ctx.issue_title + '

'      + 'Issue body:
' + ctx.issue_body
  }]
};
return [{ json: requestBody }];

const claudeText = $input.first().json.content[0].text;
const ctx = $('Prepare Branch Data').first().json;
// Parse SUMMARY line and details
let summary = 'Implementation analysis complete for issue #' + ctx.issue_number + '.';
let details = claudeText;
const parts = claudeText.split(/^---$/m);
if (parts.length >= 2) {
  const summaryLine = parts[0].trim();
  const match = summaryLine.match(/^SUMMARY:\s*(.+)/i);
  if (match) summary = match[1].trim();
  details = parts.slice(1).join('---').trim();
}
const body = '> \uD83E\uDD16 **This is an automated message from the DevLLMOps AI Agent**\n\n'
  + '**' + summary + '**\n\n'
  + '<details>\n<summary>View full implementation analysis</summary>\n\n'
  + details + '\n\n'
  + '---\n'
  + '*Branch: `' + ctx.branch_name + '`*\n\n'
  + '</details>';
return [{ json: { body, repo: ctx.repo, issue_number: ctx.issue_number, analysis_text: claudeText, branch_name: ctx.branch_name, issue_title: ctx.issue_title, issue_body: ctx.issue_body, sha: ctx.sha } }];

const tree = $input.first().json.tree || [];
const textExts = ['.py', '.js', '.ts', '.html', '.css', '.json', '.yml', '.yaml', '.md', '.txt', '.cfg', '.ini', '.toml', '.sh'];
const selected = tree.filter(item => {
  if (item.type !== 'blob') return false;
  const path = item.path;
  const ext = path.substring(path.lastIndexOf('.'));
  if (!textExts.includes(ext)) return false;
  if (path.startsWith('app/src/')) return true;
  if (!path.includes('/') && ext) return true;
  if (path === 'app/requirements.txt' || path === 'app/Dockerfile') return true;
  return false;
}).slice(0, 25);
return selected.map(item => ({ json: { path: item.path, sha: item.sha } }));

const items = $input.all();
const ctx = $('Build Analysis Comment').first().json;
const claudeMdRaw = $('Fetch CLAUDE.md').first().json.content || '';
let claudeMd = '';
try { claudeMd = Buffer.from(claudeMdRaw.replace(/\n/g, ''), 'base64').toString('utf8'); } catch(e) {}
let filesContext = '';
let totalLen = 0;
const maxLen = 80000;
for (const item of items) {
  if (!item.json.content) continue;
  let decoded;
  try { decoded = Buffer.from(item.json.content.replace(/\n/g, ''), 'base64').toString('utf8'); } catch(e) { continue; }
  const entry = '\n--- FILE: ' + item.json.path + ' ---\n' + decoded + '\n';
  if (totalLen + entry.length > maxLen) break;
  filesContext += entry;
  totalLen += entry.length;
}
const prompt = 'You are an expert software developer. Implement the following feature based on the issue description and analysis.\n\n'
  + (claudeMd ? 'PROJECT CONTEXT (CLAUDE.md):\n' + claudeMd + '\n\n' : '')
  + 'ISSUE TITLE: ' + ctx.issue_title + '\n\n'
  + 'ISSUE BODY:\n' + ctx.issue_body + '\n\n'
  + 'AI ANALYSIS:\n' + ctx.analysis_text + '\n\n'
  + 'CURRENT SOURCE FILES:\n' + filesContext + '\n\n'
  + 'INSTRUCTIONS:\n'
  + '- Implement the feature described in the issue\n'
  + '- Only modify or create files that are necessary\n'
  + '- Follow existing code conventions and patterns\n'
  + '- Keep changes minimal and focused\n\n'
  + 'RESPONSE FORMAT (strictly follow this):\n'
  + 'For each file you want to create or modify, output exactly:\n'
  + 'FILE: path/to/file\n'
  + 'ACTION: create|update\n'
  + 'CONTENT:\n'
  + '<entire file content>\n'
  + 'FILE_END\n\n'
  + 'Rules:\n'
  + '- FILE path must be repo-relative (e.g. app/src/main.py)\n'
  + '- ACTION is "create" for new files, "update" for existing\n'
  + '- CONTENT must be the COMPLETE file content (not a diff)\n'
  + '- You may output multiple FILE blocks\n'
  + '- Do not include any text outside of FILE blocks';
const requestBody = {
  model: 'claude-sonnet-4-6',
  max_tokens: 16384,
  messages: [{ role: 'user', content: prompt }]
};
return [{ json: requestBody }];

const claudeText = $input.first().json.content[0].text;
const blocks = [];
const regex = /FILE:\s*(.+)\nACTION:\s*(create|update)\nCONTENT:\n([\s\S]*?)\nFILE_END/g;
let match;
while ((match = regex.exec(claudeText)) !== null) {
  blocks.push({
    path: match[1].trim(),
    action: match[2].trim(),
    content: match[3]
  });
}
if (blocks.length === 0) throw new Error('No FILE/ACTION/CONTENT/FILE_END blocks found in Claude response');
return blocks.map(b => ({ json: b }));

const shaItems = $input.all();
const fileItems = $('Parse Implementation Files').all();
const ctx = $('Build Analysis Comment').first().json;
const results = [];
for (let i = 0; i < fileItems.length; i++) {
  const file = fileItems[i].json;
  const shaData = shaItems[i] ? shaItems[i].json : {};
  const encoded = Buffer.from(file.content).toString('base64');
  const payload = {
    path: file.path,
    action: file.action,
    message: '[auto-develop] ' + file.action + ' ' + file.path,
    content: encoded,
    branch: ctx.branch_name,
    repo: ctx.repo
  };
  if (shaData.sha) payload.sha = shaData.sha;
  results.push({ json: payload });
}
return results;

const items = $input.all();
const ctx = $('Build Analysis Comment').first().json;
const fileList = items.map(item => {
  const c = item.json.content;
  const path = (c && c.path) ? c.path : (item.json.path || 'unknown');
  return '- `' + path + '`';
}).join('\n');
const body = '> \uD83E\uDD16 **This is an automated message from the DevLLMOps AI Agent**\n\n'
  + '**Auto-develop: ' + items.length + ' file(s) committed to branch `' + ctx.branch_name + '`.**\n\n'
  + '<details>\n<summary>View committed files</summary>\n\n'
  + fileList + '\n\n'
  + '---\n'
  + '*CI will run automatically. If tests pass, a PR will be created by WF03.*\n\n'
  + '</details>';
return [{ json: { body, repo: ctx.repo, issue_number: ctx.issue_number } }];
